// Input: rows from Google Sheets Trigger
const rows = $input.all();
const out = [];

for (const item of rows) {
  const j = item.json;

  const url = j['Upload Report File'] || '';
  // supports both ?id=... and /d/.../view URLs
  const m =
    url.match(/[?&]id=([^&]+)/) ||
    url.match(/\/d\/([a-zA-Z0-9_-]+)/);

  out.push({
    json: {
      reporter: j['Reporter Name'] || null,
      category: j['Report Category'] || null,
      timestamp: new Date(j['Timestamp']).toISOString(),
      folder_id: m ? m[1] : null,
      email: j['Email Address'] || null,
      description: j['Description'] || null,
    },
  });
}

return out;
